// SPDX-License-Identifier: MIT
pragma solidity 0.8.15;

contract WillThrow {
    function aFunction() public pure  {
        require(false, "error message1");
    }
}

contract ErrorHandling {
    function catchTheError() public {
        WillThrow will = new WillThrow();
        will.aFunction();
    }
}

